// Types and loaders for the course content in public/data (generated by tools/build_app_data.py)
export type Run = { x: string; b: boolean; i: boolean; c: "aux" | "red" | "blue" | "green" | null };
export type Drill = { t: "drill"; page: number; n: number; prompt: string; formula: number | null; hl: string[]; audio?: string; answers: string[] };
export type Block =
  | { t: "page"; n: number }
  | { t: "h2" | "h3" | "p"; runs: Run[] }
  | { t: "li"; mark: string; runs: Run[] }
  | { t: "grid" | "table"; rows: (Run[] | null)[][] }
  | { t: "idiom"; idiom: string; meaning: string; example: string }
  | Drill
  | { t: "reveal"; key: string; prompt: string; answer: string }
  | { t: "quiz"; id: string };
export type LessonMeta = { id: string; num: string; title: string; stage: string; subs: string[]; first: number; last: number;
  drills: number; audio: number; audioPage: number | null; quizzes: string[]; extra?: string[]; drillKeys: string[] };
export type Stage = { id: string; title: string; desc: string };
export type Course = { stages: Stage[]; lessons: LessonMeta[]; pageLesson: Record<string, string>; placement: string[] };
export type Option = { text: string; feedback: string; correct: boolean };
type QuizBase = { id: string; title: string; order: number; lessons: string[] };
export type Quiz = QuizBase & (
  | { type: "multiple-choice"; questions: { question: string; options: Option[] }[] }
  | { type: "sentence-order"; segments: string[]; answers: string[] }
  | { type: "matching"; pairs: { left: string; right: string }[] });
export type Voice = { right: string[]; wrong: string[] };
export type Homenaje = { secciones: { id: string; titulo: string; texto: string; imagen?: string }[] };

const get = <T,>(p: string): Promise<T> => fetch(p).then((r) => { if (!r.ok) throw new Error(p); return r.json(); });
export type AllData = { course: Course; quizzes: Record<string, Quiz>; quizList: Quiz[]; voice: Voice; homenaje: Homenaje };
export async function loadAll(): Promise<AllData> {
  const [course, qs, voice, homenaje] = await Promise.all([
    get<Course>("/data/course.json"), get<Quiz[]>("/data/quizzes.json"),
    get<Voice>("/data/voice.json"), get<Homenaje>("/data/homenaje.json"),
  ]);
  return { course, quizList: qs, quizzes: Object.fromEntries(qs.map((q) => [q.id, q])), voice, homenaje };
}
const lessonCache = new Map<string, Promise<Block[]>>();
export const loadLesson = (id: string) => { if (!lessonCache.has(id)) lessonCache.set(id, get<Block[]>(`/data/lessons/${id}.json`)); return lessonCache.get(id)!; };
let searchIndex: Promise<[string, number, string][]> | null = null;
export const loadSearch = () => (searchIndex ||= get<[string, number, string][]>("/data/search.json"));

export const FORMULAS: Record<number, [string, string]> = {
  1: ["Afirmativa", "S + V + C"], 2: ["Afirmativa con 21", "S + 21 + V + C"], 3: ["Negativa", "S + 21 + N + V + C"],
  4: ["Interrogativa", "21 + S + V + C"], 5: ["Interrogativa negativa", "21 + N + S + V + C"],
};
export const pageImg = (n: number) => `/pages/${String(n).padStart(3, "0")}.webp`;
